import pandas as pd

df = pd.DataFrame({
    "product": ["A", "B", "A", "C", "B"],
    "price":   [10, 5, 10, 20, 5],
    "qty":     [1, 4, 2, 1, 3],
})

def summary(data):
    rev = data["price"] * data["qty"]
    totals = rev.groupby(data["product"]).sum()
    return {
        "total_revenue": int(rev.sum()),
        "num_orders": int(len(data)),
        "top_product": str(totals.idxmax()),
    }
